import json

# Try to find any exchange rate data in the JSON
data = json.load(open('/app/resources/treasury_bulletin_1956_03.json'))

def search_nested(obj, key_prefix=""):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'exchange' in k.lower() or 'rate' in k.lower() or 'rupee' in k.lower() or 'inr' in k.lower():
                results.append(f"{key_prefix}{k}: {str(v)[:200]}")
            results.extend(search_nested(v, f"{key_prefix}{k}: "))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_nested(item, f"{key_prefix}[{i}]: "))
    return results

results = search_nested(data)
for r in results[:20]:
    print(r)
EOF
